INSERT INTO public.site_images (id, section, name, description, desktop_url, mobile_url, alt_text, order_index, is_active, image_metadata) SELECT 'b1a9fe96-abc4-46f2-952b-8ef96a6c24cd', 'themed-party-scenarios', 'gatsby', 'Wieczór Gatsby dla firmy: muzyka, dekoracje, światło i kasyno rozrywkowe. Poznaj przykładowy program, zakres obsługi i realizację MAVINCI.', 'https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783086186282-y197ir.jpg', NULL, 'Wieczór Gatsby / Lata 20. — oprawa wydarzenia MAVINCI', 0, true, '{"content":{"title":"Impreza firmowa w stylu Gatsby i lat 20.","metaTitle":"Impreza Gatsby dla firm — wieczór w stylu lat 20. | MAVINCI","description":"Wieczór Gatsby dla firmy: muzyka, dekoracje, światło i kasyno rozrywkowe. Poznaj przykładowy program, zakres obsługi i realizację MAVINCI.","lead":"Złoto, pióra i taneczny wieczór inspirowany latami 20. Motyw Gatsby może połączyć elegancki bankiet, jubileusz firmy i swobodną integrację. W MAVINCI dobieramy do niego muzykę, prowadzenie, dekoracje oraz technikę.","summary":"Gatsby sprawdza się, gdy chcesz zachować uroczysty charakter spotkania, a jednocześnie zaprosić gości do wspólnej zabawy. Zaczynamy od celu wydarzenia i układu sali: miejsca na kolację, wystąpienia, parkiet i dodatkowe atrakcje. Motyw nie wymaga od wszystkich kostiumów — klimat można zbudować wybranymi dekoracjami, światłem i muzyką. Przy scenariuszu dla firmy ustalamy także ton prowadzenia, zakres personalizacji i przejście od części oficjalnej do tanecznej.","occasion":"Jubileusz firmy, bankiet po konferencji, gala z podziękowaniami lub elegancka integracja pracowników.","program":[{"heading":"Powitanie w klimacie lat 20.","text":"Muzyka na wejście i światło budują atmosferę, a prowadzący wprowadza gości w program. Jeżeli wybierzesz strefę zdjęciową, umieszczamy ją tak, aby nie blokowała wejścia do sali."},{"heading":"Kolacja i część firmowa","text":"Zapowiedzi, podziękowania lub przemówienia otrzymują swoje miejsce w scenariuszu. Z realizatorami ustalamy wejścia mikrofonów, muzyki i materiałów firmy, a z obiektem momenty serwisu."},{"heading":"Integracja przy wybranej atrakcji","text":"Kasyno rozrywkowe lub krótki quiz mogą stworzyć okazję do rozmów między zespołami. Ich obecność, zasady i czas działania zapisujemy w uzgodnionym programie."},{"heading":"Wieczór taneczny","text":"DJ rozwija część taneczną według ustalonego kierunku muzycznego. Występ instrumentalisty lub artysty może być osobnym punktem, po potwierdzeniu dostępności i warunków technicznych."}],"scope":[{"heading":"Dekoracje i oprawa sali","text":"Wybieramy elementy inspirowane art déco, złotem i piórami. Ustalamy konkretne dekoracje, miejsca ich ustawienia i zakres strefy zdjęciowej; nie każdy wariant wymaga przebudowy całej sali."},{"heading":"Muzyka i prowadzenie","text":"Dobieramy DJ-a, charakter zapowiedzi i repertuar. Inspiracje swingiem można połączyć z muzyką taneczną dobraną do gości. Występy na żywo wyceniamy w ustalonym zakresie."},{"heading":"Technika podporządkowana programowi","text":"Własne nagłośnienie Meyer Sound LINA, oświetlenie i multimedia pozwalają zaplanować przemówienia oraz parkiet w jednej realizacji. Zestaw dobieramy do akustyki, wielkości sali i scenariusza."}],"planning":["Miejsce na dekoracje i parkiet oraz możliwość montażu przed kolacją.","Zakres wystąpień firmowych i ewentualne materiały na ekran.","Decyzja o kasynie, strefie zdjęciowej i występach dodatkowych.","Dobrowolny dress code i informacja dla uczestników przed wydarzeniem."],"evidenceIntro":"W portfolio pokazujemy rzeczywistą realizację urodzinową w stylu Gatsby. Dokumentuje naszą pracę przy muzyce, dekoracjach, scenie, świetle i kasynie. Dla wydarzenia firmowego zmieniamy scenariusz oraz zakres, a miejsce tej realizacji nie jest przypisywane do miasta Twojego zapytania.","faq":[{"question":"Czy impreza Gatsby nadaje się na wieczór po konferencji?","answer":"Tak. Możemy połączyć kolację, podziękowania i część taneczną. Ważne jest ustalenie, czy korzystamy z tej samej sali oraz ile czasu obiekt udostępnia na zmianę oprawy i próby."},{"question":"Czy wszyscy goście muszą mieć stroje z lat 20.?","answer":"Nie. Dress code może być dobrowolny. Dekoracje, światło i muzyka wystarczą do zaznaczenia motywu, a organizator może zaproponować gościom prosty akcent w stroju."},{"question":"Czy kasyno i muzycy są w każdym wariancie?","answer":"Nie. Dobieramy je do programu i budżetu, a zakres potwierdzamy w ofercie. Kasyno eventowe jest rozrywką bez zakładów pieniężnych; występy muzyków wymagają uzgodnienia dostępności."},{"question":"Od czego zależy koszt wieczoru Gatsby?","answer":"Od terminu, miejsca, liczby gości, długości programu, wybranych dekoracji i atrakcji. Wpływ mają również dojazd, dostęp do sali i czas potrzebny na montaż. Wycena wskazuje konkretne elementy realizacji."}]}}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.site_images WHERE section = 'themed-party-scenarios' AND name = 'gatsby');

INSERT INTO public.site_images (id, section, name, description, desktop_url, mobile_url, alt_text, order_index, is_active, image_metadata) SELECT '811084a6-1d03-41c9-b36f-199cc0c5e592', 'themed-party-scenarios', 'las-vegas', 'Impreza firmowa Las Vegas: kasyno rozrywkowe, DJ, prowadzenie i oprawa sali. Sprawdź pomysł na wieczór, wybór atrakcji oraz realizacje MAVINCI.', 'https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085155276-k68hm.jpg', NULL, 'Wieczór w stylu Las Vegas — oprawa wydarzenia MAVINCI', 1, true, '{"content":{"title":"Wieczór Las Vegas i Casino Night dla firm","metaTitle":"Las Vegas i Casino Night — impreza firmowa | MAVINCI","description":"Impreza firmowa Las Vegas: kasyno rozrywkowe, DJ, prowadzenie i oprawa sali. Sprawdź pomysł na wieczór, wybór atrakcji oraz realizacje MAVINCI.","lead":"Rozmowy przy stołach, emocje wspólnej zabawy i muzyka na parkiecie. Wieczór Las Vegas łączy kasyno rozrywkowe z oprawą całego spotkania firmowego — od powitania po finał imprezy.","summary":"Ten motyw daje gościom kilka sposobów udziału: grę przy stołach, rozmowę i taniec. Sprawdza się po konferencji lub podczas spotkania różnych działów firmy, gdy organizator chce pozostawić uczestnikom swobodę wyboru aktywności. Ustalamy, czy kasyno ma być głównym punktem programu, czy działać obok DJ-a i pozostałych atrakcji. Rozmieszczenie stołów planujemy razem z parkietem oraz obsługą sali, aby poszczególne strefy nie przeszkadzały sobie nawzajem.","occasion":"Wieczorna integracja po szkoleniu, spotkanie pracowników i partnerów, jubileusz lub bankiet firmowy.","program":[{"heading":"Powitanie i zasady zabawy","text":"Prowadzący przedstawia plan wieczoru oraz sposób udziału w kasynie. Uczestnicy dostają jasną informację, że jest to zabawa bez zakładów pieniężnych."},{"heading":"Otwarcie stołów","text":"Goście poznają zasady wybranych gier z obsługą kasyna. Ruletkę, blackjacka lub poker dobieramy do przestrzeni, liczby uczestników i charakteru spotkania."},{"heading":"Muzyka i integracja","text":"DJ i prowadzący łączą grę, rozmowy i część taneczną. Jeżeli w programie są wystąpienia firmy, planujemy przerwę w atrakcjach i odpowiedni poziom muzyki."},{"heading":"Wspólne zakończenie części kasynowej","text":"Możemy przewidzieć podsumowanie zabawy lub symboliczne wyróżnienia ustalone z organizatorem. Następnie wieczór może być kontynuowany na parkiecie."}],"scope":[{"heading":"Kasyno rozrywkowe","text":"Ustalamy rodzaje i liczbę stołów, obsługę oraz czas działania. Jeżeli potrzebujesz wyłącznie tej atrakcji na istniejącym wydarzeniu, możesz zamówić samo kasyno eventowe."},{"heading":"Motyw Las Vegas","text":"Dekoracje, kolor światła, oprawa muzyczna i komunikacja prowadzącego tworzą wspólny klimat. Konkretne elementy scenografii dobieramy do sali; motyw nie oznacza automatycznie pełnej dekoracji obiektu."},{"heading":"Dźwięk, światło i multimedia","text":"Technikę dobieramy oddzielnie dla rozmów przy stołach, komunikatów i parkietu. Ekran może pokazywać plan wieczoru lub uzgodnione materiały firmy. Sprzęt i realizatorów określamy w ofercie."}],"planning":["Powierzchnia na stoły oraz swobodne przejścia i dojście obsługi.","Czy kasyno działa równolegle z kolacją i DJ-em, czy jako osobny punkt.","Sposób udziału, zasady zabawy i ewentualne symboliczne wyróżnienia.","Dostęp do sali, transport stołów oraz godziny montażu i demontażu."],"evidenceIntro":"Poniższe realizacje pokazują kasyno w szerszej oprawie wydarzeń MAVINCI: wieczoru Gatsby i gali firmowej. To przykłady wykorzystania atrakcji, a nie deklaracja, że każda z tych imprez miała motyw Las Vegas.","faq":[{"question":"Czym różni się wieczór Las Vegas od zamówienia samego kasyna?","answer":"Samo kasyno to wybrana atrakcja z ustaloną obsługą i czasem działania. Wieczór Las Vegas może dodatkowo obejmować scenariusz całego spotkania, prowadzenie, DJ-a, dekoracje i technikę. W ofercie rozdzielamy te elementy."},{"question":"Czy trzeba znać zasady gier?","answer":"Nie. Przebieg gier i zasady udziału są wyjaśniane uczestnikom. Dobieramy formę do rozrywkowego charakteru wydarzenia firmowego."},{"question":"Czy podczas Casino Night gra się na pieniądze?","answer":"Nie. Proponujemy kasyno rozrywkowe do integracji, bez zakładów pieniężnych. Warunki udziału i ewentualne symboliczne wyróżnienia ustalamy z organizatorem przed imprezą."},{"question":"Ile miejsca i stołów potrzeba na imprezę?","answer":"Nie podajemy jednego zestawu dla każdej grupy. Potrzebujemy liczby gości, planu sali oraz informacji, czy kasyno będzie jedyną atrakcją. Na tej podstawie określamy układ, obsługę i zakres wyceny."}]}}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.site_images WHERE section = 'themed-party-scenarios' AND name = 'las-vegas');

INSERT INTO public.site_images (id, section, name, description, desktop_url, mobile_url, alt_text, order_index, is_active, image_metadata) SELECT 'f6b245c4-7089-4f8c-84fe-618032b3b541', 'themed-party-scenarios', 'hollywood', 'Wieczór Hollywood z galą firmowych wyróżnień, muzyką i multimediami. Poznaj scenariusz, wymagania techniczne oraz realizację gali MAVINCI.', 'https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084888692-45zq2w.jpg', NULL, 'Wieczór w stylu Hollywood — oprawa wydarzenia MAVINCI', 2, true, '{"content":{"title":"Impreza Hollywood i gala filmowa dla firmy","metaTitle":"Impreza Hollywood dla firm — gala filmowa | MAVINCI","description":"Wieczór Hollywood z galą firmowych wyróżnień, muzyką i multimediami. Poznaj scenariusz, wymagania techniczne oraz realizację gali MAVINCI.","lead":"Filmowy motyw, który nadaje oprawę firmowym osiągnięciom. Łączymy ceremonię wyróżnień, prowadzenie, muzykę i multimedia z dalszą częścią rozrywkową wieczoru.","summary":"Hollywood jest dobrym punktem wyjścia dla firmy, która chce podsumować rok, wyróżnić zespoły lub uczcić jubileusz. Najpierw układamy część oficjalną: kategorie nagród, kolejność wejść i treści wyświetlane na ekranie. Następnie łączymy ją z kolacją oraz zabawą. Dzięki temu dekoracja filmowa wspiera konkretną historię firmy, a uczestnicy wiedzą, kiedy skupić uwagę na scenie. Wspólnie ustalamy, jak uroczysty ma być ton prowadzenia i ile miejsca zostawić na humor.","occasion":"Gala nagród pracowniczych lub sprzedażowych, podsumowanie roku, jubileusz firmy i uroczysty finał konferencji.","program":[{"heading":"Wejście gości i otwarcie gali","text":"Uzgodniona oprawa wejścia, muzyka i prowadzący wprowadzają w filmowy klimat. Strefę zdjęciową lub czerwony dywan dobieramy do miejsca oraz zakresu dekoracji."},{"heading":"Wyróżnienia i historia firmy","text":"Prowadzący zapowiada kategorie, a realizatorzy uruchamiają przygotowane materiały, muzykę i światło. Przed galą ustalamy kolejność osób, nazwiska oraz sposób wejścia na scenę."},{"heading":"Kolacja i uzgodniony program artystyczny","text":"Przerwy dopasowujemy do serwisu obiektu. Występ muzyczny, pokaz lub inny punkt artystyczny dobieramy do programu i potwierdzamy oddzielnie w ofercie."},{"heading":"Przejście do zabawy","text":"Po zakończeniu ceremonii zmieniamy charakter muzyki i światła. DJ prowadzi część taneczną; quiz filmowy lub kasyno mogą stanowić dodatkową, uzgodnioną atrakcję."}],"scope":[{"heading":"Scenariusz i prowadzenie gali","text":"Ustalamy kolejność wystąpień, zapowiedzi i momentów wręczenia nagród. Informacje o laureatach oraz materiały firmy otrzymujemy od organizatora, aby przygotować spójny przebieg ceremonii."},{"heading":"Światło, ekran i dźwięk","text":"Mikrofony, oświetlenie sceny i ekrany LED lub telewizory dobieramy do sali. Nasze zaplecze obejmuje Meyer Sound LINA oraz multimedia. Realizatorzy łączą wejścia materiałów z prowadzeniem wydarzenia."},{"heading":"Dekoracje i część wieczorna","text":"Filmową scenografię, oprawę muzyczną i atrakcje wybieramy według programu. Wygląd statuetek, dodatkowe pokazy i rejestrację wydarzenia uzgadniamy osobno; nie są automatyczną częścią każdego wariantu."}],"planning":["Lista kategorii, laureatów i osób wręczających nagrody.","Termin dostarczenia prezentacji, filmów, nazwisk oraz logotypów.","Miejsce na scenę, czytelność ekranu i trasa wejścia wyróżnianych osób.","Czas próby technicznej oraz powiązanie ceremonii z kolacją."],"evidenceIntro":"Gala Oskary Sprzedaży 2023 to realizacja MAVINCI łącząca filmową scenografię, ekran LED, program artystyczny, kasyno i obsługę techniczną. W portfolio pokazujemy jej zdjęcia oraz faktyczny zakres prac.","faq":[{"question":"Czy można przygotować galę z własnymi kategoriami nagród?","answer":"Tak. Nazwy kategorii, wyróżniane osoby i charakter podziękowań ustalamy z firmą. Organizator dostarcza zatwierdzone informacje, na których opieramy zapowiedzi i materiały do wyświetlenia."},{"question":"Jakich materiałów potrzebujecie przed galą?","answer":"Uzgadniamy listę laureatów i osób występujących, prezentacje, filmy oraz logotypy. Wyznaczamy termin przekazania plików i czas na próbę, żeby sprawdzić ich kolejność, format i zgodność ze scenariuszem."},{"question":"Czy motyw Hollywood sprawdzi się bez wręczania nagród?","answer":"Tak. Można oprzeć wieczór na muzyce filmowej, dekoracjach i programie integracyjnym, np. quizie. Ceremonia wyróżnień jest jednym z możliwych formatów, a nie obowiązkowym elementem."},{"question":"Czy zapewniacie również technikę konferencji przed galą?","answer":"Możemy połączyć oba zakresy w jednym harmonogramie. Ustalamy wykorzystanie nagłośnienia, mikrofonów, światła i multimediów oraz czas potrzebny na zmianę ustawienia sali przed wieczorem."}]}}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.site_images WHERE section = 'themed-party-scenarios' AND name = 'hollywood');

UPDATE public.site_images SET image_metadata = '{"items":[{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085155276-k68hm.jpg","title":"Wieczór w stylu Las Vegas","keywords":"impreza Las Vegas, wieczór kasynowy, event kasyno, impreza glamour","description":"Kasyno rozrywkowe z ruletką, blackjackiem lub pokerem jako przestrzeń do rozmów i wspólnej zabawy. Goście poznają zasady przy stołach, a program można połączyć z DJ-em i oprawą glamour. Dobór stołów, dekoracji i godzin gry ustalamy w ofercie; zabawa odbywa się bez zakładów pieniężnych.","scenario_slug":"las-vegas"},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085396952-8u8olr.jpg","title":"Wieczór w klimacie PRL","keywords":"impreza PRL, wieczór retro, event lata 80, zabawa w stylu PRL","description":"Wieczór retro dla firm: muzyka znana z dawnych dekad, stylizowana oprawa i wspólny quiz. Pytania oraz zabawy mogą nawiązywać do historii firmy i wspomnień uczestników. Charakter dekoracji, prowadzenie i program dobieramy do grupy."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085741224-317f1r.jpg","title":"Wieczór James Bond","keywords":"impreza James Bond, wieczór Casino Royale, event szpiegowski","description":"Elegancki motyw szpiegowski na bankiet lub integrację. Kasyno rozrywkowe, muzyka filmowa i quiz mogą tworzyć kolejne części wieczoru. Scenariusz, dekoracje i ewentualne występy artystyczne wymagają osobnego ustalenia w ofercie."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783086186282-y197ir.jpg","title":"Wieczór Gatsby / Lata 20.","keywords":"impreza Gatsby, wieczór lat 20, event art deco, charleston party","description":"Motyw lat 20. na galę, jubileusz firmy lub taneczny wieczór. Łączymy oprawę inspirowaną art déco z muzyką i prowadzeniem; program można rozszerzyć o kasyno rozrywkowe oraz występ artystyczny. Wybrane elementy i ich zakres potwierdzamy przed realizacją.","scenario_slug":"gatsby"},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084794669-c69xof.jpg","title":"Wieczór disco / lata 80.","keywords":"impreza disco, wieczór lat 80, event retro disco","description":"Taneczna integracja z DJ-em, przebojami dawnych dekad i światłem dopasowanym do parkietu. Muzyczny quiz lub teleturniej może otworzyć wieczór i pomóc zespołom się poznać. Repertuar i poziom aktywności uczestników ustalamy wspólnie."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084888692-45zq2w.jpg","title":"Wieczór w stylu Hollywood","keywords":"impreza Hollywood, wieczór filmowy, gala oscarowa","description":"Filmowa oprawa gali z podziękowaniami, prezentacją osiągnięć i wręczeniem firmowych wyróżnień. Scenariusz łączy wystąpienia, muzykę i materiały na ekranie z późniejszą zabawą. Dekoracje, multimedia i prowadzenie dobieramy do miejsca oraz programu.","scenario_slug":"hollywood"},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084809399-v1awaj.jpg","title":"Wieczór w stylu włoskim - Dolce Vita","keywords":"impreza włoska, wieczór dolce vita, event italia","description":"Swobodny wieczór firmowy inspirowany włoską atmosferą: muzyka, rozmowy i taneczna część spotkania. Klimat budujemy wybraną oprawą oraz światłem. Menu uzgadniamy z organizatorem i obiektem; catering lub dodatkowe pokazy nie są domyślnym elementem realizacji."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783084359164-c1wv2.jpg","title":"Wieczór maskaradowy - Wenecja","keywords":"bal maskowy, wieczór wenecki, maskarada firmowa","description":"Motyw weneckiego balu na elegancką imprezę firmową. Maski, zaproszenie do wspólnego dress code’u i muzyka mogą połączyć gości wokół jednego tematu. Dobieramy prowadzenie, oprawę świetlną i zakres dekoracji do wybranego scenariusza."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783083904539-3xm6q.jpg","title":"Wieczór hawajski - Aloha Party","keywords":"","description":"Tropikalny motyw na mniej formalną integrację: rytmy latino, taniec i wspólna zabawa. Wieczór można rozpocząć quizem lub teleturniejem zespołowym. Dekoracje, muzykę oraz aktywności dopasowujemy do sali i uczestników; realizacja plenerowa wymaga planu na pogodę."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085834769-shlyn9.jpg","title":"Wieczór Mafijny - Ojciec Chrzestny","keywords":"","description":"Filmowy motyw na stylizowany bankiet: elegancki dress code, odpowiednio dobrana muzyka i światło. Program można uzupełnić o kasyno rozrywkowe lub quiz filmowy. Zakres scenografii i atrakcji potwierdzamy w indywidualnej ofercie."}]}'::jsonb, updated_at = now() WHERE id = '4f4faf1e-b723-4438-8b57-fb441077c34e' AND image_metadata IS NOT DISTINCT FROM '{"items":[{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085155276-k68hm.jpg","title":"Wieczór w stylu Las Vegas","keywords":"impreza Las Vegas, wieczór kasynowy, event kasyno, impreza glamour","description":"Kasyno rozrywkowe z ruletką, blackjackiem lub pokerem jako przestrzeń do rozmów i wspólnej zabawy. Goście poznają zasady przy stołach, a program można połączyć z DJ-em i oprawą glamour. Dobór stołów, dekoracji i godzin gry ustalamy w ofercie; zabawa odbywa się bez zakładów pieniężnych."},{"image":"https://fuuljhhuhfojtmmfmskq.supabase.co/storage/v1/object/public/site-images/themed-party/1783085396952-8u8olr.jpg","title":"Wieczór w klimacie PRL","keywords":"impreza PRL, wieczór retro, event lata 80, zabawa w stylu PRL","description":"Wieczór retro dla firm: muzyka znana z dawnych dekad, stylizowana oprawa i ws